// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address depositor, address attacker) public {
        vm.assume(amount > 0);
        vm.assume(depositor != attacker);
        vm.assume(depositor != address(0));
        vm.assume(attacker != address(0));
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();
        uint256 balanceBefore = address(c).balance;
        vm.prank(attacker);
        bool reverted = false;
        try c.migrateTo(attacker) {} catch { reverted = true; }
        assertTrue(balanceBefore == 0 || reverted);
    }
}
